stageCss:
#stage .fd-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ------------------------------------------------------------- top strip -- */
#stage .fd-top{
  height:76px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 24px; border-radius:20px;
  background:rgba(20,27,43,.75); border:1.5px solid var(--border);
  transition:border-color .3s ease;
}
#stage .fd-brand{ display:flex; align-items:center; gap:14px; flex:1; min-width:0; }
#stage .fd-cart{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(240,166,74,.14); border:1.5px solid rgba(240,166,74,.4); color:var(--warn);
}
#stage .fd-cart svg{ width:26px; height:26px; }
#stage .fd-shop{
  color:var(--text-primary); font-family:var(--font-mono); font-size:23px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
/* Nothing in the meta group may wrap — at 1080px a wrapped counter collapses
   the strip and the whole header jumps a stage later. */
#stage .fd-meta{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:10px; white-space:nowrap; }
#stage .fd-orders{ color:#fff; font-family:var(--font-mono); font-size:30px; font-weight:700; font-variant-numeric:tabular-nums; }
#stage .fd-orders-l{ color:var(--text-dim); font-size:21px; font-weight:600; }
#stage .fd-health{
  align-self:center; margin-left:12px; display:flex; align-items:center; gap:9px;
  padding:8px 16px; border-radius:100px;
  border:1.5px solid rgba(63,185,80,.45); background:rgba(63,185,80,.1);
  transition:border-color .3s ease, background .3s ease;
}
#stage .fd-health i{
  width:11px; height:11px; border-radius:50%; background:var(--success);
  box-shadow:0 0 12px var(--success); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .fd-health b{ color:var(--success); font-family:var(--font-mono); font-size:20px; font-weight:700; }
#stage .fd-health.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.12); }
#stage .fd-health.warn i{ background:var(--warn); box-shadow:0 0 12px var(--warn); animation-duration:.6s; }
#stage .fd-health.warn b{ color:var(--warn); }
#stage .fd-health.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.12); }
#stage .fd-health.bad i{ background:var(--danger); box-shadow:0 0 12px var(--danger); animation-duration:.5s; }
#stage .fd-health.bad b{ color:var(--danger); }

/* ----------------------------------------------------------- scene stack -- */
#stage .fd-body{ position:relative; flex:1; min-height:0; }
#stage .fd-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.985); pointer-events:none;
  transition:opacity .32s ease, transform .32s cubic-bezier(.22,1,.36,1);
}
#stage .fd-sc.on{ opacity:1; transform:none; }

/* ===================== SCENE 1 · THE DATACENTER FLOOR ==================== */
#stage .fd-dc{
  position:relative; width:100%; height:100%;
  display:flex; flex-direction:column; gap:10px;
  padding:38px 22px 20px;
  border:2px solid rgba(58,160,255,.34); border-radius:30px;
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.1), transparent 58%), rgba(20,27,43,.42);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .fd-dc.alert{
  border-color:rgba(244,74,106,.7);
  box-shadow:0 0 0 1px rgba(244,74,106,.28), 0 0 70px rgba(244,74,106,.2);
  animation:fd-alertPulse 1s ease-in-out infinite;
}
#stage .fd-dc-tag{
  position:absolute; top:-17px; left:26px; display:flex; align-items:center; gap:10px;
  padding:5px 18px; border-radius:100px;
  background:var(--bg-deep); border:1.5px solid rgba(58,160,255,.5);
  color:var(--accent-1); font-family:var(--font-mono); font-size:19px;
  font-weight:700; letter-spacing:1.6px; white-space:nowrap;
}
#stage .fd-dc-tag svg{ width:22px; height:22px; }

/* ------------------------------------------------------- the alarm wash -- */
/* Weighted over rack A so the failure has a location, not just a colour. */
#stage .fd-alarm{
  position:absolute; inset:0; z-index:4; pointer-events:none; border-radius:30px;
  opacity:0; overflow:hidden;
  background:radial-gradient(circle at 25% 64%, rgba(244,74,106,.3), transparent 52%);
  transition:opacity .3s ease;
}
#stage .fd-alarm.on{ opacity:1; animation:fd-siren 1.05s ease-in-out infinite; }
/* A full-width opaque banner rather than a floating pill: it has to completely
   cover the shopper row it lands on, or the two read as overlapping text. */
#stage .fd-alarm-b{
  position:absolute; top:28px; left:16px; right:16px; height:72px;
  display:flex; align-items:center; justify-content:center; gap:14px;
  border-radius:16px; white-space:nowrap;
  background:linear-gradient(180deg,#2a0d16,#1a070e); border:2px solid var(--danger); color:var(--danger);
  box-shadow:0 0 46px rgba(244,74,106,.45), inset 0 0 30px rgba(244,74,106,.12);
}
#stage .fd-alarm-b svg{ width:26px; height:26px; }
#stage .fd-alarm-b b{ font-family:var(--font-mono); font-size:22px; font-weight:800; letter-spacing:1.6px; }

/* ------------------------------------------------------------- shoppers -- */
#stage .fd-clients{ flex-shrink:0; height:64px; display:flex; align-items:center; justify-content:center; gap:10px; }
#stage .fd-face{
  width:56px; height:56px; border-radius:50%; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338);
  border:1.5px solid var(--border);
  color:var(--text-primary); font-family:var(--font-mono); font-size:22px; font-weight:700;
}
#stage .fd-face-more{ background:rgba(58,160,255,.14); border-color:rgba(58,160,255,.4); color:var(--accent-1); font-size:18px; }
#stage .fd-clients-l{ margin-left:12px; color:var(--text-dim); font-family:var(--font-mono); font-size:20px; font-weight:600; white-space:nowrap; }

#stage .fd-pipe{ flex-shrink:0; height:34px; display:flex; align-items:center; justify-content:center; }
#stage .fd-pipe i{
  position:relative; width:6px; height:100%; border-radius:3px; overflow:hidden;
  background:rgba(139,149,167,.22);
}
#stage .fd-pipe.flow i{ background:rgba(58,160,255,.28); }
#stage .fd-pipe.flow i::after{
  content:""; position:absolute; left:0; right:0; height:16px; top:-16px;
  background:var(--accent-cyan); box-shadow:0 0 18px var(--accent-cyan);
  animation:fd-drop .8s linear infinite;
}

/* -------------------------------------------------------- load balancer -- */
#stage .fd-lb{
  flex-shrink:0; display:flex; align-items:center; gap:18px; padding:16px 22px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border); border-radius:20px;
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .fd-lb.live{ border-color:rgba(58,160,255,.6); box-shadow:0 0 0 1px rgba(58,160,255,.3), 0 0 48px rgba(58,160,255,.22); }
#stage .fd-lb.hot{ border-color:rgba(34,211,238,.75); box-shadow:0 0 0 1px rgba(34,211,238,.35), 0 0 60px rgba(34,211,238,.28); }
#stage .fd-lb-ic{
  width:56px; height:56px; border-radius:15px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.12); color:var(--accent-1);
  transition:background .3s ease, color .3s ease;
}
#stage .fd-lb.live .fd-lb-ic{ background:var(--accent-1); color:#0E1420; }
#stage .fd-lb.hot .fd-lb-ic{ background:var(--accent-cyan); color:#0E1420; }
#stage .fd-lb-ic svg{ width:30px; height:30px; }
#stage .fd-lb-b{ display:flex; flex-direction:column; gap:4px; min-width:0; }
#stage .fd-lb-b b{ color:#fff; font-size:28px; font-weight:800; letter-spacing:-.4px; }
#stage .fd-lb-b span{ color:var(--text-dim); font-family:var(--font-mono); font-size:19px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }

#stage .fd-badge{
  margin-left:auto; flex-shrink:0; padding:7px 15px; border-radius:9px;
  background:rgba(63,185,80,.14); border:1px solid rgba(63,185,80,.4);
  color:var(--success); font-family:var(--font-mono); font-size:19px; font-weight:700; letter-spacing:1.2px;
  white-space:nowrap; transition:background .3s ease, border-color .3s ease, color .3s ease;
}
#stage .fd-badge.warn{ background:rgba(240,166,74,.16); border-color:rgba(240,166,74,.45); color:var(--warn); }
#stage .fd-badge.bad{ background:rgba(244,74,106,.16); border-color:rgba(244,74,106,.45); color:var(--danger); }
#stage .fd-badge.off{ background:rgba(139,149,167,.12); border-color:rgba(139,149,167,.32); color:var(--text-dim); }

/* ------------------------------------------------------------- fan-out --- */
#stage .fd-fan{ position:relative; flex-shrink:0; height:62px; }
#stage .fd-fan-svg{ width:100%; height:100%; display:block; overflow:visible; }
#stage .fd-arm{
  fill:none; stroke:rgba(139,149,167,.3); stroke-width:4; stroke-linecap:round;
  transition:stroke .3s ease, opacity .3s ease;
}
#stage .fd-arm.on{ stroke:var(--accent-1); stroke-dasharray:10 14; animation:msd-dash 1.1s linear infinite; }
#stage .fd-arm.surge{ stroke:var(--accent-cyan); stroke-width:6; stroke-dasharray:12 12; animation:msd-dash .55s linear infinite; }
#stage .fd-arm.off{ stroke:rgba(244,74,106,.4); stroke-dasharray:5 11; animation:none; opacity:.5; }
#stage .fd-pct{
  position:absolute; top:14px; padding:5px 14px; border-radius:100px; font-style:normal;
  background:var(--bg-deep); border:1.5px solid var(--border);
  color:var(--text-primary); font-family:var(--font-mono); font-size:20px; font-weight:700;
  opacity:0; transition:opacity .3s ease, color .3s ease, border-color .3s ease;
}
#stage .fd-pct.show{ opacity:1; }
#stage .fd-pct.hot{ color:var(--accent-1); border-color:rgba(58,160,255,.55); }
#stage .fd-pct.max{ color:var(--accent-cyan); border-color:rgba(34,211,238,.6); }
#stage .fd-pct.dead{ color:var(--danger); border-color:rgba(244,74,106,.5); }
#stage .fd-pct-l{ left:19%; }
#stage .fd-pct-r{ right:19%; }

/* ---------------------------------------------------------- the racks ---- */
#stage .fd-racks{ flex:1; min-height:0; display:flex; gap:20px; }
#stage .fd-col{
  flex:1; min-width:0; display:flex; flex-direction:column; gap:8px;
  transition:opacity .3s ease, filter .3s ease;
}

/* The 3D tilt lives on .fd-rack and nothing else — MSD.punch/shake/focus write
   inline transforms, so they are only ever aimed at the untilted .fd-col. */
#stage .fd-rack{
  position:relative; flex:1; min-height:0;
  display:flex; flex-direction:column; gap:10px; padding:14px 16px;
  background:linear-gradient(180deg,#18213a,#111828);
  border:1.5px solid var(--border); border-radius:20px;
  box-shadow:0 26px 60px rgba(0,0,0,.5), inset 0 1px 0 rgba(255,255,255,.05);
  transition:border-color .35s ease, box-shadow .35s ease, filter .45s ease, background .45s ease;
}
#stage .fd-rack-l{ transform:perspective(1500px) rotateY(7deg); transform-origin:right center; }
#stage .fd-rack-r{ transform:perspective(1500px) rotateY(-7deg); transform-origin:left center; }
#stage .fd-rack.live{ border-color:rgba(63,185,80,.55); box-shadow:0 0 0 1px rgba(63,185,80,.22), 0 26px 60px rgba(0,0,0,.5), 0 0 50px rgba(63,185,80,.15); }
#stage .fd-rack.surge{ border-color:rgba(34,211,238,.65); box-shadow:0 0 0 1px rgba(34,211,238,.3), 0 26px 60px rgba(0,0,0,.5), 0 0 66px rgba(34,211,238,.24); }
/* Power loss: the whole cabinet loses its light, not just its status text. */
#stage .fd-rack.dark{
  border-color:rgba(244,74,106,.55);
  background:linear-gradient(180deg,#141019,#0b0810);
  filter:brightness(.55) saturate(.35);
  box-shadow:0 0 0 1px rgba(244,74,106,.24), 0 26px 60px rgba(0,0,0,.6);
}

#stage .fd-rack-h{ flex-shrink:0; display:flex; align-items:center; gap:11px; }
#stage .fd-rack-h b{ color:#fff; font-size:26px; font-weight:800; letter-spacing:.4px; }
#stage .fd-rdot{
  width:12px; height:12px; border-radius:50%; flex-shrink:0;
  background:rgba(139,149,167,.5); transition:background .3s ease, box-shadow .3s ease;
}
#stage .fd-rack.live .fd-rdot{ background:var(--success); box-shadow:0 0 14px var(--success); animation:msd-breathe 2.1s ease-in-out infinite; }
#stage .fd-rack.dark .fd-rdot{ background:var(--danger); box-shadow:0 0 12px var(--danger); animation:msd-breathe .55s ease-in-out infinite; }
#stage .fd-tag{
  margin-left:auto; flex-shrink:0; padding:6px 13px; border-radius:8px; white-space:nowrap;
  background:rgba(34,211,238,.12); border:1px solid rgba(34,211,238,.34);
  color:var(--accent-cyan); font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:.8px;
  transition:background .3s ease, border-color .3s ease, color .3s ease;
}
#stage .fd-tag.same{ background:rgba(244,74,106,.14); border-color:rgba(244,74,106,.42); color:var(--danger); }
#stage .fd-tag.ping{ animation:msd-flash .55s ease-out; }

/* --------------------------------------------------------- rack blades --- */
#stage .fd-blades{ flex:1; min-height:0; display:flex; flex-direction:column; gap:8px; }
#stage .fd-blade{
  flex:1; min-height:0; display:flex; align-items:center; gap:12px; padding:0 14px;
  background:linear-gradient(180deg,#1b2438,#151d2f);
  border:1px solid rgba(139,149,167,.18); border-radius:11px;
  transition:border-color .3s ease, background .3s ease, box-shadow .3s ease;
}
#stage .fd-blade b{
  flex-shrink:0; width:96px;
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:700;
  transition:color .3s ease;
}
/* A blade that is one of ours reads brighter than the neighbours sharing the
   cabinet — the rack has other tenants, and that is the point of a rack. */
#stage .fd-blade.fd-vm{
  background:linear-gradient(180deg,#1d2b45,#16203a);
  border-color:rgba(58,160,255,.4);
  box-shadow:inset 0 0 22px rgba(58,160,255,.1);
}
#stage .fd-blade.fd-vm b{ color:#fff; font-size:22px; font-weight:800; }
#stage .fd-rack.live .fd-blade.fd-vm{ border-color:rgba(63,185,80,.5); box-shadow:inset 0 0 22px rgba(63,185,80,.12); }

#stage .fd-led{
  width:12px; height:12px; border-radius:50%; flex-shrink:0;
  background:var(--success); box-shadow:0 0 12px var(--success);
  animation:msd-breathe 2.4s ease-in-out infinite;
  transition:background .3s ease, box-shadow .3s ease;
}
#stage .fd-blade:nth-child(2) .fd-led{ animation-delay:.3s; }
#stage .fd-blade:nth-child(3) .fd-led{ animation-delay:.6s; }
#stage .fd-blade:nth-child(4) .fd-led{ animation-delay:.9s; }
/* Dead rack: every LED out. This one line is what sells the blackout. */
#stage .fd-rack.dark .fd-led{ background:#3a3040; box-shadow:none; animation:none; }
#stage .fd-rack.dark .fd-blade{ border-color:rgba(139,149,167,.12); }
#stage .fd-rack.dark .fd-blade b{ color:#5c5566; }

#stage .fd-load{ flex:1; min-width:0; height:9px; border-radius:5px; background:rgba(139,149,167,.16); overflow:hidden; }
#stage .fd-load em{
  display:block; width:0%; height:100%; border-radius:5px;
  background:linear-gradient(90deg, var(--accent-1), var(--accent-cyan));
  transition:width .6s cubic-bezier(.22,1,.36,1), background .3s ease;
}
#stage .fd-rack.dark .fd-load em{ background:rgba(139,149,167,.3); }

/* ------------------------------------------------- shared rack utilities -- */
#stage .fd-util{ flex-shrink:0; display:flex; gap:7px; }
#stage .fd-u{
  flex:1; min-width:0; display:flex; align-items:center; justify-content:center; gap:6px;
  padding:7px 4px; border-radius:9px; white-space:nowrap;
  background:rgba(63,185,80,.1); border:1px solid rgba(63,185,80,.3);
  color:var(--success); font-family:var(--font-mono); font-size:15px; font-weight:700; letter-spacing:.8px;
  transition:background .3s ease, border-color .3s ease, color .3s ease;
}
#stage .fd-u svg{ width:15px; height:15px; flex-shrink:0; }
#stage .fd-rack.dark .fd-u{
  background:rgba(244,74,106,.12); border-color:rgba(244,74,106,.36); color:var(--danger);
  text-decoration:line-through;
}

#stage .fd-rack-f{
  flex-shrink:0; height:26px; text-align:center;
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
  transition:color .3s ease;
}
#stage .fd-rack-f.good{ color:var(--success); }
#stage .fd-rack-f.hot{ color:var(--accent-cyan); }
#stage .fd-rack-f.bad{ color:var(--danger); }

/* --------------------------------------------------------- verdict strip -- */
#stage .fd-strip{
  flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:13px 20px; border-radius:18px;
  background:rgba(20,27,43,.85); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .fd-strip-l{
  flex-shrink:0; padding:6px 14px; border-radius:8px;
  background:rgba(139,149,167,.14); border:1px solid rgba(139,149,167,.32);
  color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:1.4px;
  transition:background .3s ease, border-color .3s ease, color .3s ease;
}
#stage .fd-strip b{ color:var(--text-primary); font-size:23px; font-weight:700; line-height:1.25; }
#stage .fd-strip.good{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.09); }
#stage .fd-strip.good .fd-strip-l{ background:rgba(63,185,80,.16); border-color:rgba(63,185,80,.45); color:var(--success); }
#stage .fd-strip.good b{ color:#fff; }
#stage .fd-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.09); }
#stage .fd-strip.bad .fd-strip-l{ background:rgba(244,74,106,.16); border-color:rgba(244,74,106,.45); color:var(--danger); }
#stage .fd-strip.bad b{ color:#fff; }

/* ======================= SCENE 2 · THE TITLE REVEAL ====================== */
#stage .fd-term{
  width:100%; height:100%;
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:16px;
  padding:28px 30px;
  border:2px solid rgba(58,160,255,.42); border-radius:30px;
  background:radial-gradient(circle at 50% 16%, rgba(58,160,255,.16), transparent 62%), rgba(20,27,43,.5);
}
#stage .fd-term-k{
  color:var(--accent-cyan); font-family:var(--font-mono); font-size:20px;
  font-weight:700; letter-spacing:3.4px; text-align:center;
}
#stage .fd-term-h{
  color:#fff; font-size:66px; font-weight:900; letter-spacing:-1.6px; text-align:center; line-height:1.05;
  text-shadow:0 0 46px rgba(58,160,255,.55);
}
#stage .fd-term-h.pop{ animation:fd-titlePop .6s cubic-bezier(.22,1,.36,1); }
#stage .fd-term-s{
  max-width:820px; text-align:center;
  color:var(--text-dim); font-size:24px; font-weight:500; line-height:1.4;
}

#stage .fd-term-g{ display:flex; align-items:center; gap:26px; margin-top:14px; }
#stage .fd-mini{
  width:212px; display:flex; flex-direction:column; align-items:center; gap:9px;
  padding:18px 18px; border-radius:18px;
  background:linear-gradient(180deg,#18213a,#111828);
  border:1.5px solid rgba(63,185,80,.45);
  box-shadow:0 0 40px rgba(63,185,80,.14);
}
#stage .fd-mini-t{ color:var(--accent-cyan); font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:1.6px; }
#stage .fd-slat{
  width:100%; height:20px; border-radius:5px;
  background:rgba(139,149,167,.16); border:1px solid rgba(139,149,167,.2);
}
#stage .fd-slat-on{
  background:linear-gradient(90deg, rgba(63,185,80,.4), rgba(34,211,238,.3));
  border-color:rgba(63,185,80,.55); box-shadow:0 0 16px rgba(63,185,80,.35);
}
#stage .fd-mini-f{ margin-top:4px; color:#fff; font-family:var(--font-mono); font-size:21px; font-weight:800; }
#stage .fd-vs{
  width:56px; height:56px; border-radius:50%; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(244,74,106,.12); border:2px solid rgba(244,74,106,.45); color:var(--danger);
}
#stage .fd-vs svg{ width:28px; height:28px; }

#stage .fd-props{ display:flex; gap:11px; margin-top:8px; }
#stage .fd-prop{
  display:flex; align-items:center; gap:10px; padding:12px 18px; border-radius:100px;
  background:rgba(20,27,43,.85); border:1.5px solid var(--border); color:var(--accent-1);
}
#stage .fd-prop svg{ width:22px; height:22px; flex-shrink:0; }
#stage .fd-prop b{ color:var(--text-primary); font-size:21px; font-weight:700; white-space:nowrap; }

/* ========================== SCENE 3 · THE PAYOFF ========================= */
#stage .fd-win{
  width:100%; height:100%;
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  padding:30px 34px;
  border:2px solid rgba(63,185,80,.42); border-radius:30px;
  background:radial-gradient(circle at 50% 12%, rgba(63,185,80,.14), transparent 60%), rgba(20,27,43,.5);
}
#stage .fd-shield{
  width:104px; height:104px; border-radius:50%; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(63,185,80,.16); border:3px solid var(--success); color:var(--success);
  opacity:0; transform:scale(.5);
  transition:opacity .34s ease, transform .42s cubic-bezier(.22,1,.36,1);
}
#stage .fd-shield svg{ width:54px; height:54px; }
#stage .fd-shield.show{ opacity:1; transform:scale(1); box-shadow:0 0 0 8px rgba(63,185,80,.1), 0 0 60px rgba(63,185,80,.34); }

#stage .fd-eq{ display:flex; flex-direction:column; align-items:center; gap:8px; text-align:center; }
#stage .fd-eq-a{ color:var(--accent-1); font-size:52px; font-weight:900; letter-spacing:-1px; }
#stage .fd-eq-s{ color:var(--text-dim); font-family:var(--font-mono); font-size:38px; font-weight:700; line-height:1; }
#stage .fd-eq-b{
  color:#fff; font-size:50px; font-weight:900; letter-spacing:-1px; line-height:1.08;
  text-shadow:0 0 42px rgba(63,185,80,.45);
}

#stage .fd-win-list{ width:100%; display:flex; flex-direction:column; gap:10px; margin-top:6px; }
#stage .fd-win-i{
  display:flex; align-items:center; gap:15px; padding:14px 20px; border-radius:16px;
  background:rgba(20,27,43,.85); border:1.5px solid var(--border);
}
#stage .fd-win-i i{
  width:34px; height:34px; border-radius:50%; flex-shrink:0; font-style:normal;
  display:flex; align-items:center; justify-content:center;
  background:rgba(63,185,80,.16); border:1.5px solid rgba(63,185,80,.45);
  color:var(--success); font-size:19px; font-weight:800;
}
#stage .fd-win-i b{ color:var(--text-primary); font-size:25px; font-weight:700; }
#stage .fd-win-sla{
  margin-top:2px; display:flex; align-items:center; gap:14px;
  padding:12px 22px; border-radius:100px;
  background:rgba(58,160,255,.1); border:1.5px solid rgba(58,160,255,.42);
}
#stage .fd-win-sla b{ color:var(--accent-1); font-family:var(--font-mono); font-size:29px; font-weight:800; }
#stage .fd-win-sla span{ color:var(--text-dim); font-size:19px; font-weight:600; }

/* ============================ SCENE 4 · THE CTA ========================== */
#stage .fd-cta{
  width:100%; height:100%;
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  padding:30px 34px;
  border:2px solid rgba(58,160,255,.45); border-radius:30px;
  background:radial-gradient(circle at 50% 14%, rgba(58,160,255,.2), transparent 62%), rgba(20,27,43,.5);
}
#stage .fd-cta-ring{
  width:96px; height:96px; border-radius:50%; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:3px solid rgba(58,160,255,.6); color:var(--accent-1);
  box-shadow:0 0 0 8px rgba(58,160,255,.07), 0 0 60px rgba(58,160,255,.3);
  animation:msd-breathe 2.6s ease-in-out infinite;
}
#stage .fd-cta-ring svg{ width:50px; height:50px; }
#stage .fd-cta-h{
  color:#fff; font-size:52px; font-weight:900; letter-spacing:-1.1px; line-height:1.14; text-align:center;
  text-shadow:0 0 42px rgba(58,160,255,.45);
}
#stage .fd-cta-s{ color:var(--text-dim); font-size:24px; font-weight:500; text-align:center; }
#stage .fd-cta-row{ display:flex; gap:14px; margin-top:6px; }
#stage .fd-cta-b{
  display:flex; align-items:center; gap:11px; padding:15px 26px; border-radius:100px;
  background:rgba(20,27,43,.8); border:1.5px solid var(--border);
  color:var(--text-primary); font-size:23px; font-weight:700; white-space:nowrap;
}
#stage .fd-cta-b svg{ width:24px; height:24px; flex-shrink:0; }
#stage .fd-cta-p{
  border-color:rgba(58,160,255,.6); color:#fff;
  background:linear-gradient(90deg, rgba(58,160,255,.26), rgba(34,211,238,.14));
  box-shadow:0 0 40px rgba(58,160,255,.24);
}
#stage .fd-cta-next{
  display:flex; align-items:center; gap:14px; margin-top:8px;
  padding:13px 22px; border-radius:16px;
  background:rgba(20,27,43,.85); border:1.5px solid var(--border);
}
#stage .fd-cta-next-l{
  flex-shrink:0; padding:5px 13px; border-radius:8px;
  background:rgba(34,211,238,.14); border:1px solid rgba(34,211,238,.4);
  color:var(--accent-cyan); font-family:var(--font-mono); font-size:17px; font-weight:700; letter-spacing:1.4px;
}
#stage .fd-cta-next b{ color:var(--text-primary); font-size:21px; font-weight:600; }

/* ============================== KEYFRAMES =============================== */
@keyframes fd-drop{ to{ transform:translateY(120px); } }
@keyframes fd-siren{ 0%,100%{ opacity:.45; } 50%{ opacity:1; } }
@keyframes fd-alertPulse{
  0%,100%{ box-shadow:0 0 0 1px rgba(244,74,106,.28), 0 0 50px rgba(244,74,106,.16); }
  50%{ box-shadow:0 0 0 1px rgba(244,74,106,.5), 0 0 90px rgba(244,74,106,.34); }
}
@keyframes fd-titlePop{ 0%{ transform:scale(.86); opacity:0; } 60%{ transform:scale(1.04); } 100%{ transform:scale(1); opacity:1; } }

